import { binaryCifHasCategory, binaryCifHasColumn, getBinaryCifHeader } from '../../mol-io/common/binary-cif.js';
import { Task } from '../../mol-task/index.js';
import { PluginStateObject } from '../objects.js';
export function DataFormatProvider(provider) { return provider; }
export function rawDataObject(data) {
    return data instanceof Uint8Array
        ? new PluginStateObject.Data.Binary(data)
        : new PluginStateObject.Data.String(data);
}
/** Applies a transformer directly, without adding nodes to the state tree. */
export function applyTransformerRaw(plugin, ctx, transformer, a, params) {
    const p = transformer.createDefaultParams(a, plugin);
    if (params) {
        for (const k of Object.keys(params)) {
            if (params[k] !== undefined)
                p[k] = params[k];
        }
    }
    // no built-in transformer uses the spine, which is only available during a state update
    const result = transformer.definition.apply({ a, params: p, cache: {}, spine: undefined }, plugin);
    return Task.is(result) ? Task.resolveInContext(result, ctx) : result;
}
export function guessCifVariant(info, data) {
    if (info.ext === 'bcif') {
        try {
            const header = getBinaryCifHeader(data);
            if (header.encoder.startsWith('VolumeServer'))
                return 'dscif';
            // Assumes volseg-volume-server only serves segments
            if (header.encoder.startsWith('volseg-volume-server'))
                return 'segcif';
            if (binaryCifHasCategory(header, '_volume_data_3d_info')) {
                if (binaryCifHasCategory(header, '_volume_data_3d'))
                    return 'dscif';
                if (binaryCifHasCategory(header, '_segmentation_data_3d'))
                    return 'segcif';
            }
            if (binaryCifHasCategory(header, '_refln')) {
                if (binaryCifHasColumn(header, '_refln', 'pdbx_FWT') || binaryCifHasColumn(header, '_refln', 'pdbx_DELFWT')) {
                    return 'sfcif';
                }
            }
        }
        catch (e) {
            console.error(e);
        }
    }
    else if (info.ext === 'cif') {
        const str = data;
        if (str.startsWith('data_SERVER\n#\n_density_server_result'))
            return 'dscif';
        if (str.startsWith('data_SERVER\n#\ndata_SEGMENTATION_DATA'))
            return 'segcif';
        if (cifHasCategory(str, 'volume_data_3d_info')) {
            if (cifHasCategory(str, 'volume_data_3d'))
                return 'dscif';
            if (cifHasCategory(str, 'segmentation_data_3d'))
                return 'segcif';
        }
        // Structure factor CIF: has _refln category with map coefficients
        if (str.includes('_refln.pdbx_FWT') || str.includes('_refln.pdbx_DELFWT'))
            return 'sfcif';
        if (str.includes('atom_site_fract_x') || str.includes('atom_site.fract_x'))
            return 'coreCif';
    }
    return -1;
}
function cifHasCategory(file, categoryName) {
    return file.includes(`_${categoryName}.`);
}
